def f(g):
    out=[r[:] for r in g]
    for i,r in enumerate(out):
        # trailing run
        n=len(r); j=n-1
        while j>=0 and r[j]==r[n-1]: j-=1
        lend=r[n-1]
        lp=j+1  # length of preceding run (if any)
        if len(r)-lp>0 and lend<=lp:
            for c in range(j+1,n): out[i][c]=1
    return out
